import {
  collectPatternNames,
  collectExportedNames,
  getAST,
  isBuiltInComponent,
  JSX_EXTENSIONS,
  visitReferences,
} from '@mintlify/common';
import { visit } from 'unist-util-visit';

import type { FileContext, FileRule, FileFinding } from '../../types.js';

const getDeclared = (context: FileContext): Set<string> => {
  const declared = new Set<string>();
  visit(context.tree, 'mdxjsEsm', (node) => {
    for (const statement of node.data?.estree?.body ?? []) {
      if (statement.type === 'ImportDeclaration') {
        for (const specifier of statement.specifiers) {
          collectPatternNames(specifier.local, declared);
        }
      } else if (statement.type === 'ExportNamedDeclaration') {
        const declaration = statement.declaration;
        if (declaration?.type === 'VariableDeclaration') {
          for (const declarator of declaration.declarations) {
            collectPatternNames(declarator.id, declared);
          }
        } else if (declaration) {
          collectPatternNames(declaration.id, declared);
        }
        for (const specifier of statement.specifiers) {
          collectPatternNames(specifier.local, declared);
          collectPatternNames(specifier.exported, declared);
        }
      } else if (statement.type === 'ExportDefaultDeclaration') {
        const declaration = statement.declaration;
        if (declaration.type === 'FunctionDeclaration' || declaration.type === 'ClassDeclaration') {
          collectPatternNames(declaration.id, declared);
        }
      }
    }
  });
  return declared;
};

const getImportPosition = (context: FileContext): number => {
  const frontmatter = context.tree.children.find((child) => ['yaml', 'toml'].includes(child.type));
  return frontmatter?.position?.end.offset ?? 0;
};

const getSpecifier = (snippet: string, file: string, name: string): string | undefined => {
  let exported: Set<string>;
  try {
    exported = collectExportedNames(getAST(snippet, file));
  } catch {
    return undefined;
  }
  if (exported.has(name)) return `{ ${name} }`;
  return exported.has('default') ? name : undefined;
};

export const unknownComponent: FileRule = {
  id: 'unknown-component',
  group: 'content',
  severity: 'warning',
  scope: 'file',
  description: 'JSX components that are not built in, imported or exported',
  pagesOnly: true,
  check: (context) => {
    const declared = getDeclared(context);
    const reported = new Set<string>();
    const issues: FileFinding[] = [];
    const insertAt = getImportPosition(context);
    const prefix = insertAt === 0 ? '' : '\n\n';
    const following = /^\n*/.exec(context.content.slice(insertAt))?.[0].length ?? 0;
    const suffix = '\n'.repeat(Math.max(0, 2 - following));

    const check = (
      tag: string | null | undefined,
      position: { line?: number; column?: number } | undefined
    ) => {
      const name = tag?.split('.')[0];
      if (!tag || !name || !/^[A-Z]/.test(name)) return;
      if (declared.has(name) || reported.has(tag) || isBuiltInComponent(tag)) return;
      reported.add(tag);

      const file = JSX_EXTENSIONS.map((extension) => `snippets/${name}${extension}`).find(
        (candidate) => context.readFile?.(candidate) !== undefined
      );
      const source = file && context.readFile?.(file);
      const specifier =
        file && source !== undefined && tag === name ? getSpecifier(source, file, name) : undefined;
      issues.push({
        line: position?.line,
        column: position?.column,
        message: `<${tag}> is not built in, imported or exported on this page`,
        edit: specifier
          ? {
              start: insertAt,
              end: insertAt,
              text: `${prefix}import ${specifier} from "/${file}";${suffix}`,
            }
          : undefined,
      });
    };

    const checkJsxInExpression = (estree: unknown, fallback?: { line?: number; column?: number }) =>
      visitReferences(estree, new Set(), {
        reference: (identifier) => {
          if (identifier.type !== 'JSXIdentifier') return;
          const loc = identifier.loc as { start?: { line: number; column: number } } | undefined;
          check(String(identifier.name), loc?.start ?? fallback);
        },
      });

    visit(context.tree, (node) => {
      if (node.type === 'mdxJsxFlowElement' || node.type === 'mdxJsxTextElement') {
        check(node.name, node.position?.start);
        for (const attribute of node.attributes) {
          const value = attribute.type === 'mdxJsxAttribute' ? attribute.value : attribute;
          if (value && typeof value === 'object') {
            checkJsxInExpression(value.data?.estree, node.position?.start);
          }
        }
      } else if (node.type === 'mdxFlowExpression' || node.type === 'mdxTextExpression') {
        checkJsxInExpression(node.data?.estree, node.position?.start);
      }
    });
    return issues;
  },
};
